import{_ as t,a,c as r,ac as s}from"./chunks/framework.BSuaGltH.js";const x=JSON.parse('{"title":"Nuxt SSR排障：不匹配、404、缓存与部署","description":"沿HTML、payload、请求作用域和Node产物定位SSR故障；示例未执行，给出未来验证步骤。","frontmatter":{"title":"Nuxt SSR排障：不匹配、404、缓存与部署","description":"沿HTML、payload、请求作用域和Node产物定位SSR故障；示例未执行，给出未来验证步骤。","showdocs":{"topics":[{"id":"vue","title":"Vue","link":"/topics/vue/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Nuxt SSR：请求作用域与本地课程目录","summary":"沿HTML、payload、请求作用域和Node产物定位SSR故障；示例未执行，给出未来验证步骤。","status":"active","related":[{"title":"Nuxt SSR：首屏、注水与请求作用域","link":"/programming/web-plus/vue/plus/subjects/ssr-model","kind":"响应式与组件","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目","link":"/programming/web-plus/vue/plus/practice/ssr-application","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录的手写契约约定了什么至Nuxt本地API怎样限制输入和响应数据","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-01","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录后续怎样安装和验收至练习：扩展公开课程","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-02","kind":"开发实践","scope":"general","audience":"general"},{"title":"Nuxt SSR数据：稳定键、序列化与保密边界","link":"/programming/web-plus/vue/plus/subjects/ssr-data","kind":"响应式与组件","scope":"general","audience":"general"}],"prev":{"text":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录后续怎样安装和验收至练习：扩展公开课程","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Nuxt SSR实践：本地课程目录完整项目 · Nuxt课程目录后续怎样安装和验收至练习：扩展公开课程","link":"/programming/web-plus/vue/plus/practice/ssr-application-part-02"},"next":false},"headers":[],"relativePath":"programming/web-plus/vue/plus/troubleshooting/ssr-diagnostics.md","filePath":"programming/web-plus/vue/plus/troubleshooting/ssr-diagnostics.md"}'),o={name:"programming/web-plus/vue/plus/troubleshooting/ssr-diagnostics.md"};function n(i,e,l,u,p,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="nuxt-ssr排障-不匹配、404、缓存与部署" tabindex="-1">Nuxt SSR排障：不匹配、404、缓存与部署 <a class="header-anchor" href="#nuxt-ssr排障-不匹配、404、缓存与部署" aria-label="Permalink to &quot;Nuxt SSR排障：不匹配、404、缓存与部署&quot;">​</a></h1><p>本篇是本地课程目录的故障推演。示例未执行，文中的操作和预期需要读者日后实测；没有真实控制台、HTTP或部署记录。排查时保留请求地址、状态码、原始HTML与最小输入，但不要记录cookie、凭据和完整个人头字段。</p><h2 id="mismatch" tabindex="-1">Nuxt出现hydration不匹配应该先检查什么 <a class="header-anchor" href="#mismatch" aria-label="Permalink to &quot;Nuxt出现hydration不匹配应该先检查什么 {#mismatch}&quot;">​</a></h2><p>Nuxt出现hydration不匹配应该先检查什么？先比较服务器HTML与浏览器首次渲染的输入，再检查非法HTML嵌套、Date或随机值以及localStorage条件。hydration不匹配是两侧首次树不一致，不能仅以最终页面看起来正确认定无问题。浏览器可能修正非法标签，Vue也可能恢复DOM，这些都会掩盖原始原因。</p><p>本例以固定fixture、payload布尔值和稳定键保证可推演的首屏，不依赖本地时区。若加入window.innerWidth，把读取推迟到onMounted并给出一致的初始回退；若加入时间，明确服务器与浏览器共用的显示输入。不要用data-allow-mismatch掩盖可修复错误，或在没有解释代价时关闭全站SSR。依据：<a href="https://nuxt.com/docs/4.x/guide/best-practices/hydration" target="_blank" rel="noopener noreferrer">Nuxt hydration建议</a>。</p><h2 id="errors" tabindex="-1">Nuxt详情404为什么要同时检查页面和API状态 <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Nuxt详情404为什么要同时检查页面和API状态 {#errors}&quot;">​</a></h2><p>Nuxt详情404为什么要同时检查页面和API状态？API状态表示资源读取结果，页面状态表示SSR响应是否正确表达不存在；只在页面显示文字却返回200，会把失败页面当成功内容。本例API无效slug或查无课程返回404，详情把404传给Nuxt错误页，其他读取失败归为503，错误页不打印原始异常。</p><p>客户端导航错误还需检查clearError返回后的应用状态；硬刷新则检查真实HTTP状态，二者不能互相替代。若代理把/api/不存在改写为index.html，读取可能收到200 HTML而非JSON，先检查Content-Type与响应源。未知页面与已匹配但课程不存在都可显示404文案，但根因分别在页面路由与业务查询。依据：<a href="https://nuxt.com/docs/4.x/getting-started/error-handling" target="_blank" rel="noopener noreferrer">Nuxt错误处理</a>。</p><h2 id="cache" tabindex="-1">Nuxt没有全局用户变量为什么仍可能串请求 <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;Nuxt没有全局用户变量为什么仍可能串请求 {#cache}&quot;">​</a></h2><p>Nuxt没有全局用户变量为什么仍可能串请求？共享缓存可以把一个请求的HTML与payload直接回给另一个请求，即使服务器useState隔离正确。欢迎语依赖Accept-Language，CDN只按路径缓存首页就会串语言；未来若含用户内容，后果可能是数据泄露。本例HTML和API均no-store，没有SWR、prerender或共享welcome缓存。</p><p>排查先看Node直连，再看反向代理和CDN实际响应头与缓存命中；源码写了no-store不能证明边缘没有覆盖。公共fixture适合共享不可变输入，不代表包含欢迎语的整页也可公共缓存。若未来缓存纯公共课程，应定义数据更新与失效规则；若做语言变体缓存，必须完整定义变体键和所有响应差异，不能仅补一个缓存时间。依据：<a href="https://nuxt.com/docs/4.x/guide/concepts/rendering" target="_blank" rel="noopener noreferrer">Nuxt渲染模式</a>。</p><h2 id="deployment" tabindex="-1">Nuxt为什么不能只上传public目录部署这个项目 <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Nuxt为什么不能只上传public目录部署这个项目 {#deployment}&quot;">​</a></h2><p>Nuxt为什么不能只上传public目录部署这个项目？public目录只有静态资源，当前项目的SSR HTML与本地API都需要Node服务器执行；node-server构建产物入口为.output/server/index.mjs，部署要保留完整.output。静态主机不会因为上传一个Vue页面就自动运行welcome handler，开发环境能访问也不证明生产具备相同运行时。</p><p>本例固定node-server preset，未做静态生成、边缘或serverless适配。生产还要验证代理路由、状态码、超时、资源路径和no-store；不能把所有404重写为SPA壳。原生Node可用的库也未必适合边缘环境。README给出读者未来安装和构建步骤，本轮未执行；运行时应由宿主注入环境变量，不能假设生产入口自动加载开发.env。依据：<a href="https://nuxt.com/docs/4.x/getting-started/deployment" target="_blank" rel="noopener noreferrer">Nuxt部署</a>。</p><h2 id="exercise" tabindex="-1">练习：代理前后差异 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习：代理前后差异 {#exercise}&quot;">​</a></h2><p>Node直连时A/en与B/zh欢迎语不同，经过CDN后都变成英文，且404详情返回200。给出两个独立假设、应收集的证据与修复后的验收，不要把两件事归咎于useState。</p><details class="details custom-block"><summary>参考答案（推演，未执行）</summary><p>语言串用优先检查CDN是否覆盖no-store并按路径缓存完整响应；404变200优先检查代理错误页/SPA fallback改写。对比直连与边缘的状态、HTML、缓存响应头和路由配置；修复后交替及并发验证语言，再硬刷新不存在详情与API，分别确认404。没有实际请求记录前只能保留假设，不能声称已定位或修复。</p></details>',17)])])}const m=t(o,[["render",n]]);export{x as __pageData,m as default};
